<template><ForgeDialog title="QR code generator" description="Generate a downloadable QR image from text or a URL." eyebrow="WORKSPACE / CONVERTER" @close="emit('close')"><div class="qr-panel"><textarea v-model="value" rows="5" placeholder="https://example.com" /><label>Error correction<select v-model="level"><option value="low">Low</option><option value="medium">Medium</option><option value="quartile">Quartile</option><option value="high">High</option></select></label><div class="qr-preview"><img v-if="image" :src="image" alt="Generated QR code" /><span v-else>Enter text to generate</span></div><button class="primary-button" :disabled="!image" @click="download">Download PNG</button></div></ForgeDialog></template>
<script setup lang="ts">
import { ref, watch } from 'vue'
import QRCode from 'qrcode'
import ForgeDialog from './ForgeDialog.vue'
const emit=defineEmits<{close:[]}>(); const value=ref(''); const level=ref<'low'|'medium'|'quartile'|'high'>('medium'); const image=ref(''); let timer:number|undefined; const regenerate=async()=>{image.value=value.value.trim()?await QRCode.toDataURL(value.value,{errorCorrectionLevel:level.value,margin:2,width:320}):''}; const download=()=>{if(!image.value)return;const a=document.createElement('a');a.href=image.value;a.download='pqt-forge-qr.png';a.click()}; watch([value,level],()=>{clearTimeout(timer);timer=window.setTimeout(()=>void regenerate(),120)})
</script>
<style scoped>.qr-panel{display:grid;gap:12px;justify-items:start}.qr-panel textarea,.qr-panel select{padding:10px;color:var(--pqt-text);background:var(--pqt-canvas);border:1px solid var(--pqt-border-strong);border-radius:7px;font:12px var(--pqt-font-mono)}.qr-panel textarea{width:100%;resize:vertical}.qr-panel label{display:grid;gap:6px;color:var(--pqt-text-muted);font-size:11px}.qr-preview{display:grid;place-items:center;width:250px;height:250px;padding:12px;border-radius:8px;background:#fff;color:#556;font-size:11px}.qr-preview img{max-width:100%;max-height:100%}</style>
